package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.util.Annotations;
import java.io.*;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AnnotationMap_addIfNotPresent_TriageGen0Test {

    private AnnotationMap annotationMap;

    @Before
    public void setUp() {
        annotationMap = new AnnotationMap();
    }

    @Test
    public void testAddIfNotPresent_NewAnnotation_ReturnsTrue() {
        // Arrange
        Annotation mockAnn = mock(Annotation.class);
        Class<?> mockType = mock(Class.class);
        when(mockAnn.annotationType()).thenReturn(mockType);

        // Act
        boolean result = annotationMap.addIfNotPresent(mockAnn);

        // Assert
        assertTrue("Should return true when adding a new annotation", result);
        assertEquals("Size should be 1", 1, annotationMap.size());
    }

    @Test
    public void testAddIfNotPresent_DuplicateAnnotation_ReturnsFalse() {
        // Arrange
        Class<?> mockType = mock(Class.class);

        Annotation ann1 = mock(Annotation.class);
        when(ann1.annotationType()).thenReturn(mockType);

        Annotation ann2 = mock(Annotation.class);
        when(ann2.annotationType()).thenReturn(mockType);

        // Act
        annotationMap.add(ann1);
        boolean result = annotationMap.addIfNotPresent(ann2);

        // Assert
        assertFalse("Should return false when annotation type already exists", result);
        assertEquals("Size should still be 1", 1, annotationMap.size());
    }

    @Test
    public void testAddIfNotPresent_DifferentAnnotationTypes_ReturnsTrue() {
        // Arrange
        Class<?> type1 = mock(Class.class);
        Class<?> type2 = mock(Class.class);

        Annotation ann1 = mock(Annotation.class);
        when(ann1.annotationType()).thenReturn(type1);

        Annotation ann2 = mock(Annotation.class);
        when(ann2.annotationType()).thenReturn(type2);

        // Act
        annotationMap.add(ann1);
        boolean result = annotationMap.addIfNotPresent(ann2);

        // Assert
        assertTrue("Should return true when adding an annotation with a different type", result);
        assertEquals("Size should be 2", 2, annotationMap.size());
    }
}
